import{_ as t}from"./chunks/landing_page_1.aE_D7HLi.js";import{_ as e}from"./chunks/go_signin_page.DptkCh_6.js";import{_ as o}from"./chunks/admin_dashboard.Dn647LHR.js";import{_ as r}from"./chunks/admin_customer.Blg61HWR.js";import{_ as s}from"./chunks/admin_products.Dua0zmzc.js";import{_ as i}from"./chunks/warehouse_stock.Cwl2XRfw.js";import{_ as n}from"./chunks/admin_stock_movements.BcAlPRnh.js";import{_ as l}from"./chunks/sales_challans.CHJjtNfL.js";import{_ as c,o as d,c as u,a2 as h}from"./chunks/framework.Ce1WstT_.js";const W=JSON.parse('{"title":"Product Tour","description":"","frontmatter":{},"headers":[],"relativePath":"project/product-tour.md","filePath":"project/product-tour.md"}'),p={name:"project/product-tour.md"};function m(g,a,_,f,y,b){return d(),u("div",null,[...a[0]||(a[0]=[h('<h1 id="product-tour" tabindex="-1">Product Tour <a class="header-anchor" href="#product-tour" aria-label="Permalink to &quot;Product Tour&quot;">​</a></h1><p>Welcome to the Fundsroom Infotech Mini ERP + CRM Operations Portal. This tour walks you through the core user experience across all major modules of the application.</p><h2 id="_1-landing-page" tabindex="-1">1. Landing Page <a class="header-anchor" href="#_1-landing-page" aria-label="Permalink to &quot;1. Landing Page&quot;">​</a></h2><p>When unauthenticated users visit the platform, they are greeted with a clean, branded landing page that communicates the product&#39;s value proposition before directing them to log in.</p><p><img src="'+t+'" alt="Landing Page"></p><p><strong>What you can do:</strong></p><ul><li>Read about the platform&#39;s features</li><li>Navigate to the Sign In portal</li></ul><h2 id="_2-authentication-login" tabindex="-1">2. Authentication (Login) <a class="header-anchor" href="#_2-authentication-login" aria-label="Permalink to &quot;2. Authentication (Login)&quot;">​</a></h2><p>The gateway to the portal enforces strict Role-Based Access Control (RBAC).</p><p><img src="'+e+'" alt="Login Page"></p><p><strong>What you can do:</strong></p><ul><li>Authenticate with an email and password</li><li>The system automatically detects your role (ADMIN, SALES, WAREHOUSE, ACCOUNTS) and routes you to the appropriate dashboard context.</li></ul><h2 id="_3-dashboard" tabindex="-1">3. Dashboard <a class="header-anchor" href="#_3-dashboard" aria-label="Permalink to &quot;3. Dashboard&quot;">​</a></h2><p>Upon successful login, you are routed to your context-aware dashboard.</p><p><img src="'+o+'" alt="Admin Dashboard"></p><p><strong>What you see:</strong></p><ul><li>High-level KPIs (Total Customers, Active Products, Low Stock Alerts)</li><li>A sidebar navigation menu tailored strictly to your permissions. (e.g., Sales cannot see the Inventory adjustment tabs).</li></ul><h2 id="_4-crm-customers" tabindex="-1">4. CRM (Customers) <a class="header-anchor" href="#_4-crm-customers" aria-label="Permalink to &quot;4. CRM (Customers)&quot;">​</a></h2><p>The CRM module is where relationships are managed.</p><p><img src="'+r+'" alt="Customers List"></p><p><strong>What you see:</strong></p><ul><li>A searchable, paginated list of all B2B and retail clients.</li><li>Status badges indicating if a customer is Active or Inactive.</li></ul><p><strong>What you can do:</strong></p><ul><li>Add new customers.</li><li>Click into a customer profile to log follow-up interactions (calls, meetings).</li></ul><h2 id="_5-products-catalog" tabindex="-1">5. Products Catalog <a class="header-anchor" href="#_5-products-catalog" aria-label="Permalink to &quot;5. Products Catalog&quot;">​</a></h2><p>The definitive master list of all sellable goods.</p><p><img src="'+s+'" alt="Products Grid"></p><p><strong>What you see:</strong></p><ul><li>Grid layout of products with their current base price, SKU, category, and real-time available stock.</li></ul><p><strong>What you can do (Admin):</strong></p><ul><li>Create new products and set their pricing and minimum stock thresholds.</li></ul><h2 id="_6-inventory-management" tabindex="-1">6. Inventory Management <a class="header-anchor" href="#_6-inventory-management" aria-label="Permalink to &quot;6. Inventory Management&quot;">​</a></h2><p>The warehouse command center for managing physical stock.</p><p><img src="'+i+'" alt="Inventory Grid"></p><p><strong>What you see:</strong></p><ul><li>A focused view on physical stock levels rather than pricing.</li></ul><p><strong>What you can do (Warehouse/Admin):</strong></p><ul><li>Click &quot;Adjust Stock&quot; on any item to log a manual IN (restock) or OUT (damage/loss) adjustment, bypassing standard sales flows.</li></ul><h2 id="_7-stock-movements" tabindex="-1">7. Stock Movements <a class="header-anchor" href="#_7-stock-movements" aria-label="Permalink to &quot;7. Stock Movements&quot;">​</a></h2><p>The immutable ledger of all inventory changes.</p><p><img src="'+n+'" alt="Stock Movements"></p><p><strong>What you see:</strong></p><ul><li>A chronological, append-only log of every time stock increased or decreased, who did it, and whether it was a manual adjustment or a sales challan deduction.</li></ul><h2 id="_8-sales-challans" tabindex="-1">8. Sales Challans <a class="header-anchor" href="#_8-sales-challans" aria-label="Permalink to &quot;8. Sales Challans&quot;">​</a></h2><p>The bridge between CRM and Inventory.</p><p><img src="'+l+'" alt="Sales Challans"></p><p><strong>What you see:</strong></p><ul><li>A list of draft, confirmed, and cancelled dispatch orders.</li></ul><p><strong>What you can do (Sales/Admin):</strong></p><ul><li>Create a new draft challan for a customer.</li><li>Add line items to the challan.</li><li><strong>Confirm</strong> the challan, which automatically checks stock, deducts inventory, and finalizes the order.</li></ul>',50)])])}const x=c(p,[["render",m]]);export{W as __pageData,x as default};
